action.query:
SELECT COUNT(*) AS total_orders, SUM(CASE WHEN ORDER_STATUS = 'CANCELLED' THEN 1 ELSE 0 END) AS total_cancelled, AVG(CASE WHEN ORDER_STATUS = 'CANCELLED' THEN 1 ELSE 0 END) AS overall_cancellation_rate
FROM ZOMATO_DLR.SOURCES.ORDERS
WHERE ORDER_DATE >= '2025-01-01' AND ORDER_DATE < '2026-01-01';
